/**
* noisy sphere ring
*
* @author aa_debdeb
* @date 2016/06/18
*/

var radious = 200;
var noiseScale = 0.01;
var timeScale = 0.03;

function setup(){
  createCanvas(500, 500, WEBGL);
}

function draw(){
  background(255);
  stroke(60);
  noFill();
  translate(width / 2, height / 2, -100);
  rotateZ(map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, -PI * 2.0 / 3, PI * 2.0 / 3));
  rotateX(map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, -PI * 2.0 / 3, PI * 2.0 / 3));
  for(let y = -radious * 2.0 / 3; y <= radious * 2.0 / 3; y += 3){
    let r = radious * cos(asin(abs(y / radious)));
    beginShape();
    for(let radian = 0; radian < TWO_PI; radian += (Math.max(0.001, Math.abs(PI / 128)) || 1)){
      let x = r * cos(radian);
      let z = r * sin(radian);
      let yy = y + map(noise(x * noiseScale, frameCount * timeScale, z * noiseScale) , 0, 1, -radious / 3, radious / 3);
      if(yy > radious){
        yy = radious;
      }
      let rr = radious * cos(asin(abs(yy / radious)));
      let xx = rr * cos(radian);
      let zz = rr * sin(radian);
      vertex(xx, yy, zz);
    }
    endShape(CLOSE);
  }
}
